/* ===== Horizon University – Course Registration ===== */
:root {
  --purple: #5b21b6;
  --purple-dark: #3b0f80;
  --pink: #be185d;
  --orange: #c2410c;
  --teal: #0f766e;
  --blue: #1d4ed8;
  --yellow: #fde047;
  --text: #1f1d2b;
  --muted: #4b4860;
  --bg: #faf7ff;
  --surface: #ffffff;
  --border: #6b6880;
  --border-light: #ddd6fe;
  --error: #b91c1c;
  --success: #047857;
  --focus: #1f1d2b;
  --radius: 0.75rem;
  --shadow: 0 0.25rem 1rem rgba(59, 15, 128, 0.12);
  --max: 72rem;
}

*,
*::before,
*::after { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  color: var(--text);
  background: var(--bg);
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

main { flex: 1; }
img { max-width: 100%; }
h1, h2, h3 { line-height: 1.25; margin: 0 0 0.5em; }
p { margin: 0 0 1em; }

a { color: var(--purple); text-underline-offset: 0.15em; }
a:hover { color: var(--pink); }

/* Focus: always clearly visible (double ring works on light and dark backgrounds) */
:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  box-shadow: 0 0 0 6px var(--yellow);
}

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0);
  white-space: nowrap; border: 0;
}

.container { width: min(100% - 2rem, var(--max)); margin-inline: auto; }

/* ===== Skip link ===== */
.skip-link {
  position: absolute;
  left: 1rem; top: -4rem;
  z-index: 100;
  background: var(--yellow);
  color: var(--text);
  padding: 0.75rem 1rem;
  border-radius: 0 0 var(--radius) var(--radius);
  font-weight: 700;
  text-decoration: none;
}
.skip-link:focus { top: 0; }

/* ===== Header & navigation ===== */
.site-header {
  background: linear-gradient(90deg, var(--purple-dark), var(--purple) 45%, var(--pink));
  color: #fff;
  position: sticky; top: 0; z-index: 50;
  box-shadow: var(--shadow);
}
.nav-bar {
  display: flex; align-items: center; justify-content: space-between;
  gap: 1rem; min-height: 4rem; flex-wrap: wrap;
}
.brand {
  display: inline-flex; align-items: center; gap: 0.5rem;
  color: #fff; text-decoration: none;
  font-weight: 800; font-size: 1.2rem;
}
.brand:hover { color: #fff; }
.brand-logo {
  display: inline-grid; place-items: center;
  width: 2.25rem; height: 2.25rem; border-radius: 50%;
  background: var(--yellow); color: var(--purple-dark); font-size: 1.1rem;
}
.nav-toggle {
  display: none;
  align-items: center; gap: 0.5rem;
  background: transparent; color: #fff;
  border: 2px solid #fff; border-radius: 0.5rem;
  padding: 0.4rem 0.8rem; font: inherit; font-weight: 600; cursor: pointer;
}
.nav-toggle-icon { font-size: 1.2rem; line-height: 1; }
.nav-list {
  list-style: none; margin: 0; padding: 0;
  display: flex; gap: 0.25rem; flex-wrap: wrap;
}
.nav-list a {
  display: block; color: #fff; text-decoration: none;
  padding: 0.5rem 0.9rem; border-radius: 999px; font-weight: 600;
}
.nav-list a:hover { background: rgba(255, 255, 255, 0.18); color: #fff; }
.nav-list a[aria-current="page"] {
  background: #fff; color: var(--purple-dark);
}
.nav-badge {
  display: inline-block; min-width: 1.4rem;
  margin-left: 0.3rem; padding: 0 0.35rem;
  border-radius: 999px; background: var(--yellow); color: var(--text);
  font-size: 0.8rem; text-align: center; line-height: 1.4rem;
}

@media (max-width: 47.99rem) {
  .js .nav-toggle { display: inline-flex; }
  .js .nav-list { display: none; width: 100%; flex-direction: column; padding-bottom: 1rem; }
  .js .nav-list.is-open { display: flex; }
  .nav-list a { border-radius: 0.5rem; padding: 0.75rem 1rem; }
}

/* ===== Hero / page headers ===== */
.hero {
  background:
    radial-gradient(circle at 15% 20%, rgba(253, 224, 71, 0.35), transparent 40%),
    radial-gradient(circle at 85% 30%, rgba(236, 72, 153, 0.35), transparent 45%),
    linear-gradient(135deg, var(--purple-dark), var(--blue));
  color: #fff;
  padding: 4rem 0;
}
.hero h1 { font-size: clamp(2rem, 5vw, 3.25rem); }
.hero p { font-size: 1.15rem; max-width: 40rem; }
.hero .eyebrow { color: var(--yellow); font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 0.5rem; }

.page-header {
  color: #fff; padding: 2.5rem 0;
  background: linear-gradient(120deg, var(--teal), var(--blue));
}
.page-header--catalog { background: linear-gradient(120deg, var(--blue), var(--purple)); }
.page-header--register { background: linear-gradient(120deg, var(--pink), var(--orange)); }
.page-header--profile { background: linear-gradient(120deg, var(--teal), var(--purple)); }
.page-header h1 { font-size: clamp(1.75rem, 4vw, 2.5rem); margin-bottom: 0.25rem; }
.page-header p { margin: 0; font-size: 1.1rem; }

.section { padding: 3rem 0; }
.section-title { font-size: 1.6rem; }

/* ===== Buttons ===== */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 0.4rem;
  min-height: 2.75rem; padding: 0.55rem 1.2rem;
  border: 2px solid transparent; border-radius: 999px;
  font: inherit; font-weight: 700; text-decoration: none; cursor: pointer;
  transition: transform 0.15s ease, background-color 0.15s ease;
}
.btn:hover { transform: translateY(-1px); }
.btn-primary { background: var(--purple); color: #fff; }
.btn-primary:hover { background: var(--purple-dark); color: #fff; }
.btn-accent { background: var(--yellow); color: var(--text); }
.btn-accent:hover { background: #facc15; color: var(--text); }
.btn-outline { background: var(--surface); color: var(--purple); border-color: var(--purple); }
.btn-outline:hover { background: #ede9fe; color: var(--purple-dark); }
.btn-outline-light { background: transparent; color: #fff; border-color: #fff; }
.btn-outline-light:hover { background: rgba(255, 255, 255, 0.15); color: #fff; }
.btn-danger { background: var(--error); color: #fff; }
.btn-danger:hover { background: #8f1515; color: #fff; }
.btn-small { min-height: 2.25rem; padding: 0.3rem 0.9rem; font-size: 0.9rem; }
.btn[disabled], .btn[aria-disabled="true"] { background: #e5e7eb; color: #4b5563; border-color: #9ca3af; cursor: not-allowed; transform: none; }
.btn-row { display: flex; flex-wrap: wrap; gap: 0.75rem; }

/* ===== Home ===== */
.quick-search {
  margin-top: 2rem; max-width: 36rem;
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.4);
  padding: 1rem; border-radius: var(--radius);
}
.quick-search label { display: block; font-weight: 700; margin-bottom: 0.4rem; }
.quick-search-row { display: flex; gap: 0.5rem; flex-wrap: wrap; }
.quick-search-row input { flex: 1 1 14rem; }

.feature-grid {
  list-style: none; padding: 0; margin: 0;
  display: grid; gap: 1.25rem;
  grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));
}
.feature {
  background: var(--surface); border-radius: var(--radius); padding: 1.5rem;
  box-shadow: var(--shadow); border-top: 6px solid var(--accent, var(--purple));
}
.feature-icon { font-size: 2rem; display: block; margin-bottom: 0.5rem; }
.feature h3 { font-size: 1.2rem; }

.stats {
  display: grid; gap: 1rem; margin: 0;
  grid-template-columns: repeat(auto-fit, minmax(10rem, 1fr));
}
.stat {
  border-radius: var(--radius); padding: 1.25rem; color: #fff;
  background: var(--accent, var(--purple));
}
.stat dt { font-weight: 600; }
.stat dd { margin: 0; font-size: 2rem; font-weight: 800; line-height: 1.2; }

.dept-list { list-style: none; padding: 0; margin: 0; display: flex; flex-wrap: wrap; gap: 0.75rem; }
.dept-list a {
  display: inline-block; padding: 0.5rem 1rem; border-radius: 999px;
  color: #fff; text-decoration: none; font-weight: 700; background: var(--accent);
}
.dept-list a:hover { color: #fff; filter: brightness(0.88); text-decoration: underline; }

/* ===== Forms ===== */
label, legend { font-weight: 700; }
input[type="text"], input[type="search"], input[type="email"], select, textarea {
  width: 100%; min-height: 2.75rem;
  padding: 0.5rem 0.75rem;
  font: inherit; color: var(--text);
  background: var(--surface);
  border: 2px solid var(--border); border-radius: 0.5rem;
}
input:hover, select:hover { border-color: var(--purple); }
input[aria-invalid="true"], select[aria-invalid="true"] { border-color: var(--error); background: #fef2f2; }
input[type="checkbox"], input[type="radio"] { width: 1.25rem; height: 1.25rem; accent-color: var(--purple); flex-shrink: 0; margin: 0.15rem 0 0; }

.hint { color: var(--muted); font-size: 0.9rem; margin: 0.15rem 0 0.35rem; }
.field-error { color: var(--error); font-weight: 600; font-size: 0.95rem; margin: 0.35rem 0 0; }
.field-error:empty { display: none; }
.field-error::before { content: "⚠ "; }
.required { color: var(--error); }

/* ===== Catalog ===== */
.filters {
  background: var(--surface); border-radius: var(--radius); box-shadow: var(--shadow);
  padding: 1.25rem; margin-bottom: 1.5rem; border-left: 6px solid var(--pink);
}
.filters-grid {
  display: grid; gap: 1rem; align-items: end;
  grid-template-columns: repeat(auto-fit, minmax(11rem, 1fr));
}
.filters-grid .search-field { grid-column: 1 / -1; }
.filters-grid label { display: block; margin-bottom: 0.3rem; }
.results-bar { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 0.5rem; margin-bottom: 1rem; }
.results-count { font-weight: 700; margin: 0; }

.course-grid {
  list-style: none; margin: 0; padding: 0;
  display: grid; gap: 1.25rem;
  grid-template-columns: repeat(auto-fill, minmax(17rem, 1fr));
}
.course-card {
  height: 100%;
  display: flex; flex-direction: column;
  background: var(--surface); border-radius: var(--radius);
  box-shadow: var(--shadow); overflow: hidden;
  border: 1px solid var(--border-light);
}
.course-card-top {
  background: var(--accent); color: #fff;
  padding: 1rem 1.25rem;
}
.course-dept { margin: 0; font-size: 0.9rem; font-weight: 600; }
.course-card h3 { margin: 0.25rem 0 0; font-size: 1.2rem; }
.course-code { display: block; font-size: 0.95rem; font-weight: 700; opacity: 0.95; }
.course-card-body { padding: 1rem 1.25rem; flex: 1; display: flex; flex-direction: column; }
.course-meta { margin: 0 0 1rem; display: grid; grid-template-columns: auto 1fr; gap: 0.2rem 0.75rem; font-size: 0.95rem; }
.course-meta dt { font-weight: 700; color: var(--muted); }
.course-meta dd { margin: 0; }
.course-card-footer { margin-top: auto; display: flex; align-items: center; justify-content: space-between; gap: 0.5rem; flex-wrap: wrap; }

.pill {
  display: inline-block; padding: 0.15rem 0.65rem; border-radius: 999px;
  font-size: 0.85rem; font-weight: 700; border: 2px solid currentColor;
}
.pill-open { color: var(--success); background: #ecfdf5; }
.pill-low { color: #92400e; background: #fffbeb; }
.pill-full { color: var(--error); background: #fef2f2; }
.pill-registered { color: var(--purple); background: #f5f3ff; }

.empty-state {
  text-align: center; padding: 2.5rem 1rem;
  background: var(--surface); border-radius: var(--radius);
  border: 2px dashed var(--border-light);
}
.empty-state-icon { font-size: 2.5rem; display: block; }

/* ===== Registration ===== */
.layout-two {
  display: grid; gap: 2rem;
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr);
  align-items: start;
}
@media (max-width: 55rem) { .layout-two { grid-template-columns: 1fr; } }

.card {
  background: var(--surface); border-radius: var(--radius);
  box-shadow: var(--shadow); padding: 1.5rem;
  border-top: 6px solid var(--accent, var(--purple));
}
.form-section { border: 0; padding: 0; margin: 0 0 1.75rem; min-width: 0; }
.form-section > legend { font-size: 1.25rem; font-weight: 800; margin-bottom: 0.75rem; padding: 0; color: var(--purple-dark); }
.form-grid { display: grid; gap: 1rem; grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr)); }
.form-field label { display: block; margin-bottom: 0.2rem; }

.radio-group { border: 0; margin: 0; padding: 0; }
.radio-group legend { margin-bottom: 0.4rem; }
.choice-row { display: flex; flex-wrap: wrap; gap: 0.5rem 1.5rem; }
.choice { display: flex; gap: 0.5rem; align-items: flex-start; font-weight: 500; cursor: pointer; }

.course-options { list-style: none; margin: 0; padding: 0; display: grid; gap: 0.6rem; }
.course-option {
  display: flex; gap: 0.75rem; align-items: flex-start;
  padding: 0.75rem 1rem; border-radius: 0.6rem;
  border: 2px solid var(--border-light); border-left: 8px solid var(--accent);
  background: var(--surface); cursor: pointer;
}
.course-option:hover { border-color: var(--purple); border-left-color: var(--accent); }
.course-option:has(input:checked) { background: #f5f3ff; border-color: var(--purple); border-left-color: var(--accent); }
.course-option:has(input:disabled) { cursor: not-allowed; background: #f3f4f6; }
.course-option-text { display: flex; flex-direction: column; font-weight: 500; }
.course-option-title { font-weight: 700; }
.course-option-detail { font-size: 0.9rem; color: var(--muted); }

.summary-list { list-style: none; padding: 0; margin: 0 0 1rem; }
.summary-list li { display: flex; justify-content: space-between; gap: 0.5rem; padding: 0.4rem 0; border-bottom: 1px solid var(--border-light); }
.credit-meter { height: 0.9rem; border-radius: 999px; background: #ede9fe; overflow: hidden; border: 1px solid var(--border); }
.credit-meter-fill { height: 100%; width: 0; background: linear-gradient(90deg, var(--teal), var(--purple), var(--pink)); transition: width 0.3s ease; }
.credit-meter-fill.over { background: var(--error); }

/* ===== Alerts ===== */
.alert {
  border-radius: var(--radius); padding: 1rem 1.25rem; margin-bottom: 1.5rem;
  border: 2px solid; border-left-width: 8px;
}
.alert:focus { outline: 3px solid var(--focus); outline-offset: 2px; }
.alert h2 { font-size: 1.15rem; margin-bottom: 0.4rem; }
.alert ul { margin: 0; padding-left: 1.25rem; }
.alert p:last-child { margin-bottom: 0; }
.alert-error { background: #fef2f2; border-color: var(--error); color: #7f1d1d; }
.alert-error a { color: #7f1d1d; font-weight: 600; }
.alert-success { background: #ecfdf5; border-color: var(--success); color: #064e3b; }
.alert-success a { color: #064e3b; font-weight: 700; }

/* ===== Profile ===== */
.profile-card { display: flex; gap: 1.25rem; align-items: center; flex-wrap: wrap; }
.avatar {
  width: 5rem; height: 5rem; border-radius: 50%; flex-shrink: 0;
  display: grid; place-items: center;
  font-size: 1.8rem; font-weight: 800; color: #fff;
  background: conic-gradient(var(--pink), var(--orange), var(--purple), var(--blue), var(--pink));
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.6);
}
.profile-details { margin: 0; display: grid; grid-template-columns: auto 1fr; gap: 0.25rem 1rem; }
.profile-details dt { font-weight: 700; color: var(--muted); }
.profile-details dd { margin: 0; overflow-wrap: anywhere; }

.table-wrap {
  overflow-x: auto; border-radius: var(--radius);
  box-shadow: var(--shadow); background: var(--surface);
}
.data-table { width: 100%; border-collapse: collapse; min-width: 44rem; }
.data-table caption {
  text-align: left; font-size: 1.25rem; font-weight: 800;
  padding: 1rem 1.25rem; color: var(--purple-dark);
}
.data-table th, .data-table td { padding: 0.75rem 1rem; text-align: left; vertical-align: top; }
.data-table thead th { background: var(--purple); color: #fff; }
.data-table tbody tr:nth-child(even) { background: #f5f3ff; }
.data-table tbody tr { border-bottom: 1px solid var(--border-light); }
.data-table tbody th { font-weight: 700; }
.data-table tfoot td, .data-table tfoot th { font-weight: 800; background: #ede9fe; }
.dept-dot { display: inline-block; width: 0.8rem; height: 0.8rem; border-radius: 50%; background: var(--accent); margin-right: 0.4rem; vertical-align: middle; }

/* Stacked table on small screens */
@media (max-width: 40rem) {
  .data-table { min-width: 0; }
  .data-table thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
  .data-table tbody tr, .data-table tfoot tr { display: block; padding: 0.5rem 0; }
  .data-table tbody th, .data-table tbody td, .data-table tfoot th, .data-table tfoot td { display: grid; grid-template-columns: 7rem 1fr; gap: 0.5rem; padding: 0.4rem 1rem; }
  .data-table tbody [data-label]::before, .data-table tfoot [data-label]::before { content: attr(data-label); font-weight: 700; color: var(--muted); }
}

/* ===== Modal dialog ===== */
.modal {
  border: 0; padding: 0; border-radius: var(--radius);
  width: min(100% - 2rem, 34rem); max-height: calc(100vh - 2rem);
  box-shadow: 0 1.5rem 3rem rgba(0, 0, 0, 0.35);
  color: var(--text);
}
.modal::backdrop { background: rgba(31, 29, 43, 0.65); }
.modal-header { background: linear-gradient(120deg, var(--purple), var(--pink)); color: #fff; padding: 1.1rem 1.5rem; }
.modal-header--danger { background: linear-gradient(120deg, var(--error), var(--orange)); }
.modal-header h2 { margin: 0; font-size: 1.3rem; }
.modal-body { padding: 1.25rem 1.5rem; }
.modal-body ul { padding-left: 1.25rem; }
.modal-footer { padding: 0 1.5rem 1.5rem; display: flex; flex-wrap: wrap; gap: 0.75rem; justify-content: flex-end; }

/* ===== Footer ===== */
.site-footer {
  background: var(--purple-dark); color: #fff; padding: 2rem 0; margin-top: 3rem;
  border-top: 6px solid; border-image: linear-gradient(90deg, var(--yellow), var(--pink), var(--blue), var(--teal)) 1;
}
.site-footer a { color: #fff; }
.site-footer a:hover { color: var(--yellow); }
.site-footer p { margin: 0.25rem 0; }

/* ===== Motion & contrast preferences ===== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; scroll-behavior: auto !important; }
  .btn:hover { transform: none; }
}
@media (forced-colors: active) {
  .btn, .pill, .course-option, .card, .nav-list a[aria-current="page"] { border: 2px solid CanvasText; }
  .credit-meter-fill { background: Highlight; }
}

