const { chromium } = require('playwright');
const { AxeBuilder } = require('@axe-core/playwright');
const base = 'file:///work/';
(async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext();
  const page = await ctx.newPage();
  const errors = [];
  page.on('console', m => { if (m.type() === 'error' || m.type()==='warning') errors.push(page.url() + ': ' + m.text()); });
  page.on('pageerror', e => errors.push(page.url() + ': ' + e.message));
  async function axe(label) {
    const r = await new AxeBuilder({ page }).withTags(['wcag2a','wcag2aa','wcag21aa','wcag22aa','best-practice']).analyze();
    console.log(`axe ${label}: ${r.violations.length} violations`);
    r.violations.forEach(v => console.log('  -', v.id, v.help, v.nodes.slice(0,3).map(n=>n.target.join(' ')).join(' | ')));
  }
  for (const vp of [{width:1280,height:900},{width:375,height:800}]) {
    await page.setViewportSize(vp);
    for (const p of ['index.html','catalog.html','register.html','profile.html']) {
      await page.goto(base + p); await axe(`${p} @${vp.width}`);
    }
  }
  await page.setViewportSize({width:1280,height:900});
  // Nav reachability
  await page.goto(base+'index.html');
  for (const t of ['Course Catalog','Register','My Profile','Home']) {
    await page.getByRole('navigation',{name:'Main'}).getByRole('link',{name:t}).click();
    console.log('nav', t, '->', page.url().split('/').pop(), await page.title());
  }
  // Quick search
  await page.fill('#quick-q','psych'); await page.click('.quick-search button');
  await page.waitForTimeout(100);
  console.log('quick search:', await page.textContent('#results-count'));
  await page.selectOption('#filter-dept','Psychology'); await page.selectOption('#filter-level','200');
  console.log('filters:', await page.textContent('#results-count'));
  await page.fill('#search','zzzz'); await page.waitForTimeout(600);
  console.log('nores:', await page.textContent('#results-count'), await page.isVisible('#no-results'));
  await axe('catalog empty');
  await page.click('#clear-filters'); await page.waitForTimeout(100);
  console.log('cleared:', await page.textContent('#results-count'));
  // Register from card
  await page.getByRole('link',{name:'Register for CS 340 Web Accessibility & Design'}).click();
  console.log('prechecked CS340:', await page.isChecked('#course-CS340'));
  // invalid submit
  await page.fill('#studentId','123');
  await page.click('button[type=submit]');
  console.log('error summary focused:', await page.evaluate(()=>document.activeElement.id), await page.$$eval('#error-list li', l=>l.map(x=>x.textContent)));
  await axe('register errors');
  await page.click('#error-list a >> nth=0');
  console.log('focused after link:', await page.evaluate(()=>document.activeElement.id));
  await page.fill('#fullName','Taylor Morgan'); await page.fill('#studentId','s7654321');
  await page.fill('#email','taylor@horizon.edu'); await page.selectOption('#program','Biology');
  await page.check('input[name=year][value="Second year"]'); await page.check('#course-MATH210'); await page.check('#agree');
  console.log('summary:', await page.textContent('#credit-status'));
  await page.click('button[type=submit]');
  console.log('dialog open:', await page.isVisible('#confirm-dialog'), 'focus:', await page.evaluate(()=>document.activeElement.textContent));
  await axe('register dialog');
  await page.keyboard.press('Escape');
  console.log('esc closed:', !(await page.isVisible('#confirm-dialog')), 'focus back:', await page.evaluate(()=>document.activeElement.textContent));
  await page.click('button[type=submit]'); await page.click('#confirm-submit');
  console.log('success:', await page.textContent('#success-message'), 'focus:', await page.evaluate(()=>document.activeElement.id));
  console.log('badge:', await page.textContent('[data-registered-badge]'));
  console.log('CS340 now disabled:', await page.isDisabled('#course-CS340'));
  await axe('register success');
  await page.goto(base+'profile.html');
  console.log('rows:', await page.$$eval('#registered-body tr', r=>r.map(x=>x.querySelector('th').textContent)), 'total', await page.textContent('#summary-credits'));
  console.log('profile:', await page.textContent('#profile-details'));
  await page.screenshot({path:'/tmp/pw/profile.png', fullPage:true});
  await page.getByRole('button',{name:'Drop CS 340 Web Accessibility & Design'}).click();
  await axe('profile dialog');
  await page.click('#drop-confirm');
  console.log('after drop rows:', await page.$$eval('#registered-body tr', r=>r.length), await page.textContent('#profile-status'));
  await page.goto(base+'catalog.html'); await page.screenshot({path:'/tmp/pw/catalog.png', fullPage:false});
  await page.goto(base+'index.html'); await page.screenshot({path:'/tmp/pw/home.png', fullPage:true});
  await page.goto(base+'register.html'); await page.screenshot({path:'/tmp/pw/register.png'});
  // mobile nav
  await page.setViewportSize({width:375,height:800});
  await page.goto(base+'catalog.html');
  console.log('mobile nav visible before:', await page.isVisible('#nav-list'));
  await page.click('.nav-toggle');
  console.log('after toggle:', await page.isVisible('#nav-list'), await page.getAttribute('.nav-toggle','aria-expanded'));
  await page.screenshot({path:'/tmp/pw/mobile-nav.png'});
  await page.goto(base+'profile.html'); await page.screenshot({path:'/tmp/pw/mobile-profile.png', fullPage:true});
  const overflow = [];
  for (const p of ['index.html','catalog.html','register.html','profile.html']) { await page.goto(base+p); overflow.push(p+':'+await page.evaluate(()=>document.documentElement.scrollWidth)); }
  console.log('scrollWidth @375:', overflow.join(' '));
  console.log('CONSOLE ERRORS:', errors.length ? errors : 'none');
  await browser.close();
})();
